// Resource-carpet fix, connected activity chains, decision evidence and persistence of a 300+ resident schema-5
// FIXTURE (synthetic, generated by the base engine; see tests/fixtures/expanse-v5-300/manifest.json).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import zlib from 'node:zlib';
import crypto from 'node:crypto';
import { Expanse, expectedHoldings, EXPANSE_SCHEMA } from '../server/src/expanse/engine.js';
import { save, load, identityDigest, backup, SNAPSHOT } from '../server/src/expanse/persist.js';
import { frame } from '../server/src/expanse/view.js';
import { CHAIN_LIMITS, materialDemand } from '../server/src/expanse/chains.js';
import { aggregatePiles, pileSizeClass } from '../shared/stockpiles.js';

const here = path.dirname(new URL(import.meta.url).pathname);
const FIX = path.join(here, 'fixtures/expanse-v5-300');
const fixtureBody = fs.readFileSync(path.join(FIX, 'expanse.json.gz'));
const fixture = () => JSON.parse(zlib.gunzipSync(fixtureBody));
const ledger = (e) => { const h = e.holdings(), x = expectedHoldings(e.totals), ks = new Set([...Object.keys(h), ...Object.keys(x)]); return [...ks].filter((k) => (h[k] ?? 0) !== (x[k] ?? 0)); };
const pileUnits = (e) => { let n = 0, piles = 0; for (const ch of e.chunks.values()) for (const p of ch.piles) { piles++; for (const v of Object.values(p.items)) n += v; } return { n, piles }; };
// Per-resident identity and learned data the change must never alter on load.
const learned = (s) => s.creatures.map((c) => ({ id: c.id, name: c.name, parents: c.parents, brain: c.brain, model: c.mind.model, episodes: c.mind.episodes, goals: c.mind.goals, goalModel: c.mind.goalModel, inventory: c.inventory, relationships: c.relationships, memories: c.memories }));

test('fixture is a representative schema-5 world with 300+ residents and accumulated ground stocks', () => {
  const man = JSON.parse(fs.readFileSync(path.join(FIX, 'manifest.json')));
  assert.equal(man.fixture, true);
  assert.equal(crypto.createHash('sha256').update(fixtureBody).digest('hex'), man.sha256);
  const s = fixture();
  assert.equal(s.schema, 5); assert.equal(EXPANSE_SCHEMA, 5);
  assert.ok(s.creatures.length >= 300, `${s.creatures.length} residents`);
  assert.ok(man.piles > 300 && man.pileUnits > 500, 'carries the base-engine log carpet');
});

test('loading the fixture with the updated engine preserves identity, learned weights, memories and inventory; save/load/restart is exact', () => {
  const s = fixture(), before = learned(s), digest = identityDigest(s);
  const e = Expanse.fromState(structuredClone(s));
  assert.deepEqual(learned(e.toState()), before, 'no learned/identity field changes on load');
  assert.equal(identityDigest(e.toState()), digest);
  assert.deepEqual(ledger(e), [], 'pre-run ledger exact');
  const pre = pileUnits(e);
  // Explicit copy + backup on disk, then save/load/restart.
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'chains-fix-')), dest = fs.mkdtempSync(path.join(os.tmpdir(), 'chains-bak-'));
  try {
    save(dir, e); backup(dir, dest);
    assert.ok(fs.existsSync(path.join(dest, SNAPSHOT)) || fs.readdirSync(dest).length > 0, 'backup written');
    const a = load(dir);
    assert.deepEqual(a.toState(), e.toState(), 'disk restart preserves the full state, including terrain, stocks and learned data');
    assert.equal(a.creatures.length, s.creatures.length); assert.equal(a.tick, s.tick); assert.equal(a.id, s.id);
    a.run(30); const b = Expanse.fromState(JSON.parse(JSON.stringify(a.toState()))); a.run(30); b.run(30);
    assert.equal(JSON.stringify(a.toState()), JSON.stringify(b.toState()), 'restart mid-run serializes identically');
    assert.deepEqual(ledger(a), [], 'post-run ledger exact');
    // No stocks deleted to clean the map: every unit is still in a pile, store or inventory per the ledger.
    const total = (h) => Object.values(h).reduce((t, n) => t + n, 0);
    assert.equal(total(a.holdings()), total(expectedHoldings(a.totals)));
    assert.ok(pre.n > 0);
  } finally { fs.rmSync(dir, { recursive: true, force: true }); fs.rmSync(dest, { recursive: true, force: true }); }
});

test('unattended run: bounded ground piles, all three chains complete, decision evidence bounded and state-derived', () => {
  const e = Expanse.create({ initialCount: 40 }, { seed: 7 });
  e.run(3500);
  assert.deepEqual(ledger(e), []);
  const { piles } = pileUnits(e);
  assert.ok(piles < 80, `ground piles stay bounded (${piles}); base engine reaches ~400 by this tick`);
  const T = e.totals.chains;
  assert.ok(T.materials.completed > 0, 'materials acquired and used for build/repair/mend');
  assert.ok(Object.keys(T.materials.byUse).some((k) => k.startsWith('repair') || k.startsWith('mend')), 'used for shelter repair or tool mending');
  assert.ok(T.food.completed > 0 && Object.keys(T.food.byOutcome).length >= 2, 'food eaten and shared/stored');
  assert.ok(T.food.cooked > 0, 'unattended residents acquire raw food, prepare it over a real shared fire, then use it');
  assert.ok(T.explore.started > 0 && T.explore.found > 0 && T.explore.returned + T.explore.settled > 0, 'search found a source and returned/settled');
  for (const ev of e.chainLog) assert.ok(['materials', 'food', 'explore'].includes(ev.kind) && Number.isInteger(ev.resident) && ev.ticks >= 0);
  for (const c of e.creatures) {
    assert.ok(c.mind.decisions.length <= CHAIN_LIMITS.decisions);
    assert.ok(Object.keys(c.mind.prov).length <= CHAIN_LIMITS.provenance);
    for (const d of c.mind.decisions) { assert.ok(d.needs && d.perceived && Array.isArray(d.chosen)); assert.ok(d.alternatives.length <= CHAIN_LIMITS.alternatives); }
  }
  assert.ok(e.chainLog.length <= CHAIN_LIMITS.log);
  const f = frame(e, { x: 0, y: 0, w: 56, h: 56, creature: e.creatures[0].id });
  assert.ok(f.chains.totals && Array.isArray(f.chains.recent));
  assert.ok(Array.isArray(f.inspector.decisions) && f.inspector.chains);
  assert.ok('pileClusters' in f.view);
});

test('tool mending consumes exactly one unit of its material and keeps the ledger exact; tools wear out with use', () => {
  const e = Expanse.create({ initialCount: 4 }, { seed: 3 });
  const c = e.creatures[0];
  c.inventory = { hand_axe: 1, flint: 1 }; c.toolWear = { hand_axe: 30 }; c.energy = 80;
  e.totals.crafted.hand_axe = (e.totals.crafted.hand_axe ?? 0) + 1; e.totals.gathered.flint = (e.totals.gathered.flint ?? 0) + 1; // staged items enter the ledger
  c.plan = { raw: [{ prim: 'mend', tool: 'hand_axe', item: 'flint', key: 'mend|hand_axe|', label: 'GATHER_STONE' }], idx: 0, actual: [], steps: [], predicted: [], demand: ['flint'] };
  e.startStep(c);
  for (let i = 0; i < 6 && c.act; i++) e.stepAct(c);
  assert.equal(c.inventory.flint, undefined); assert.equal(c.toolWear.hand_axe, 15); assert.equal(e.totals.mendUsed.flint, 1);
  assert.deepEqual(ledger(e), []);
  c.toolWear.hand_axe = 39; e.wearTool(c, 'hand_axe');
  assert.equal(c.inventory.hand_axe, undefined); assert.equal(e.totals.wornOut.hand_axe, 1);
  assert.deepEqual(ledger(e), []);
});

test('wood-only residents do not scatter fuel even when cold; material demand comes from perception', () => {
  const e = Expanse.create({ initialCount: 4 }, { seed: 3 });
  const c = e.creatures[0];
  e.dropToPile(c.x + 1, c.y, 'stick', 2);
  c.inventory = { wood: 1 }; c.warmth = 95; c.hunger = 10;
  c.mind.shelters.push({ id: 999, x: c.x + 5, y: c.y + 5, complete: true, integrity: 100, ruined: false, stock: {}, visited: e.tick, t: e.tick }); // a remembered store with room
  let obs = e.perceive(c), offers = e.affordances(c, obs)(c.inventory, null);
  assert.ok(!offers.some((s) => s.prim === 'place'), 'warm, sated resident is not offered to scatter fuel');
  assert.ok(offers.some((s) => s.prim === 'carry' && s.haul && s.x === c.x + 1), 'nearby pile can be hauled');
  c.warmth = 50; obs = e.perceive(c); offers = e.affordances(c, obs)(c.inventory, null);
  assert.ok(!offers.some((s) => s.prim === 'place'), 'cold alone cannot start a fire without ignition material');
  const site = e.newStructure(c.x + 2, c.y + 2, c.id); e.shelters.push(site);
  const d = materialDemand(e, c, e.perceive(c));
  assert.ok([...d.keys()].length > 0 && [...d.values()].every((w) => w.startsWith('site:')));
});


// Staged stock enters the same ledger as gathered stock; no production fixture is modified.
function fuelCase(items) {
  const e = Expanse.create({ initialCount: 4 }, { seed: 3 }), c = e.creatures[0];
  assert.deepEqual(c.inventory, {});
  c.inventory = { ...items }; c.warmth = 50; c.hunger = 10;
  for (const [item, n] of Object.entries(items)) e.totals.gathered[item] = (e.totals.gathered[item] ?? 0) + n;
  return { e, c };
}

for (const ignition of [{ stone: 1 }, { flint: 1, stone: 1 }]) {
  test(`ignition-ready fuel consolidates onto a perceived pile with exact accounting (${Object.keys(ignition)})`, () => {
    const { e, c } = fuelCase({ wood: 1, ...ignition });
    e.dropToPile(c.x + 1, c.y, 'stone', 2); e.totals.gathered.stone = (e.totals.gathered.stone ?? 0) + 2;
    const before = e.holdings(), piles = pileUnits(e).piles;
    const place = e.affordances(c, e.perceive(c))(c.inventory, null).find((s) => s.prim === 'place' && s.item === 'wood');
    assert.ok(place); assert.equal(place.x, c.x + 1); assert.equal(place.y, c.y);
    c.plan = { raw: [place], idx: 0, actual: [], steps: [], predicted: [], demand: [] };
    e.startStep(c);
    for (let i = 0; i < 30 && c.act; i++) e.stepAct(c);
    assert.equal(c.act, null, 'target reached and placement finished');
    assert.equal(c.inventory.wood, undefined);
    assert.equal(e.pileAt(place.x, place.y).items.wood, 1);
    assert.equal(e.pileAt(place.x, place.y).items.stone, 2);
    assert.equal(e.totals.placed.wood, 1);
    assert.equal(pileUnits(e).piles, piles, 'no extra pile created');
    assert.deepEqual(e.holdings(), before, 'placement transfers rather than consumes stock');
    assert.deepEqual(ledger(e), []);
  });
}

test('flint without stone cannot bootstrap fuel; an on-tile pile can still consolidate wood', () => {
  const { e, c } = fuelCase({ wood: 1, flint: 1 });
  assert.ok(!e.affordances(c, e.perceive(c))(c.inventory, null).some((s) => s.prim === 'place'));
  e.dropToPile(c.x, c.y, 'stick', 1); e.totals.gathered.stick = (e.totals.gathered.stick ?? 0) + 1;
  assert.ok(e.affordances(c, e.perceive(c))(c.inventory, null).some((s) => s.prim === 'place' && s.item === 'wood'));
  assert.deepEqual(ledger(e), []);
});

test('stockpile aggregation keeps exact quantities and member ids', () => {
  const piles = [{ id: 'p1', x: 1, y: 1, items: { wood: 3 } }, { id: 'p2', x: 2, y: 3, items: { wood: 1, stone: 2 } }, { id: 'p3', x: 9, y: 9, items: { fiber: 1 } }];
  const g = aggregatePiles(piles, 4);
  assert.equal(g.length, 2);
  assert.deepEqual(g[0].items, { wood: 4, stone: 2 }); assert.equal(g[0].units, 6); assert.deepEqual(g[0].members.map((m) => m.id), ['p1', 'p2']);
  assert.equal(aggregatePiles(piles, 1).reduce((t, x) => t + x.units, 0), 7);
  assert.deepEqual([0, 1, 3, 10, 40].map(pileSizeClass), [0, 1, 2, 3, 4]);
});

for (const striker of ['stone', 'flint']) {
  test(`${striker} pile strikes retain inventory in planner predictions and failed/successful execution`, async () => {
    const { plan } = await import('../server/src/expanse/agent.js');
    const { e, c } = fuelCase({ stone: 1, ...(striker === 'flint' ? { flint: 1 } : {}) });
    e.dropToPile(c.x, c.y, 'stick', 1); e.totals.gathered.stick = (e.totals.gathered.stick ?? 0) + 1;
    const inv = { ...c.inventory }, offers = e.affordances(c, e.perceive(c));
    const strikes = (inventory, prev) => offers(inventory, prev).filter((s) => s.prim === 'use' && s.on === 'pile' && s.item === striker);
    const candidates = plan(c.mind, { inventory: inv }, strikes, { horizon: 3 });
    assert.ok(candidates.some((p) => p.steps.length === 3), 'three strikes remain feasible with the same held striker');
    assert.ok(candidates.every((p) => p.steps.every((s) => s.consumes.length === 0)));
    const before = e.holdings(), next = e.rng.next;
    try {
      // Only the spark RNG is controlled: these are direct engine steps, not autonomous-run evidence.
      for (const spark of [0.999999, 0.999999, 0]) {
        e.rng.next = () => spark;
        const step = strikes(c.inventory, null)[0]; assert.ok(step);
        c.plan = { raw: [step], idx: 0, actual: [], steps: [], predicted: [], demand: [] };
        e.startStep(c); for (let i = 0; i < 10 && c.act; i++) e.stepAct(c);
        assert.equal(c.act, null);
        assert.deepEqual(c.inventory, inv, 'striker retained on both failure and success');
        assert.deepEqual(ledger(e), []);
        if (spark) { assert.deepEqual(e.holdings(), before); assert.equal(e.pileAt(c.x, c.y).items.stick, 1); assert.equal(e.fires.length, 0); }
      }
      assert.equal(e.pileAt(c.x, c.y), null);
      assert.equal(e.fires.length, 1); assert.equal(e.totals.burnedItems.stick, 1);
    } finally { e.rng.next = next; }
  });
}


test('failed ignition reuses perceived fuel without placing extra wood and reaches its exact tile', () => {
  const {e,c}=fuelCase({wood:1,stone:1});
  const target={x:c.x+1,y:c.y};
  e.dropToPile(target.x,target.y,'stick',2); e.totals.gathered.stick=2;
  const before=e.holdings(), next=e.rng.next;
  try {
    e.rng.next=()=>0.999999;
    for(let attempt=0;attempt<3;attempt++) {
      const offers=e.affordances(c,e.perceive(c))(c.inventory,null);
      assert.ok(!offers.some(s=>s.prim==='place'), 'existing fuel must not be topped up for every failed spark');
      const step=offers.find(s=>s.prim==='use'&&s.on==='pile'&&s.item==='stone');
      assert.ok(step); assert.equal(step.x,target.x);
      c.plan={raw:[step],idx:0,actual:[],steps:[],predicted:[],demand:[]}; e.startStep(c);
      for(let i=0;i<30&&c.act;i++)e.stepAct(c);
      assert.equal(c.act,null);assert.equal(c.x,target.x);assert.equal(c.y,target.y);
      assert.deepEqual(e.holdings(),before);assert.deepEqual(ledger(e),[]);
    }
    assert.equal(c.inventory.wood,1);assert.equal(pileUnits(e).piles,1);
    const step=e.affordances(c,e.perceive(c))(c.inventory,null).find(s=>s.prim==='use'&&s.on==='pile'&&s.item==='stone');
    e.rng.next=()=>0;
    c.plan={raw:[step],idx:0,actual:[],steps:[],predicted:[],demand:[]};e.startStep(c);
    for(let i=0;i<30&&c.act;i++)e.stepAct(c);
    assert.equal(e.fires.length,1);assert.equal(c.inventory.wood,1);assert.deepEqual(ledger(e),[]);
  } finally {e.rng.next=next;}
});

test('a planned fuel target disappearing aborts without igniting another tile',()=>{
  const {e,c}=fuelCase({stone:1});e.dropToPile(c.x+1,c.y,'stick',1);
  const step=e.affordances(c,e.perceive(c))(c.inventory,null).find(s=>s.prim==='use'&&s.on==='pile'&&s.item==='stone');
  assert.ok(step);const p=e.pileAt(step.x,step.y);p.items={};e.removePileIfEmpty(p);
  c.plan={raw:[step],idx:0,actual:[],steps:[],predicted:[],demand:[]};e.startStep(c);e.stepAct(c);
  assert.equal(c.act,null);assert.equal(e.fires.length,0);
});
